import { endOfDay, isBefore, startOfDay } from 'date-fns';

import { _getSecondFractions, _applyInitialTime } from './date-time.js';
import { _parseTime } from './timeParser.js';
import { _StringTimeOffset } from './types.js';
import {
  type TimeframeV2,
  _isSimpleTimeOffset,
} from '../../../core/types/time.js';
import { _CalendarState } from '../../date-picker/calendar/types/shared-types.js';

/**
 *  Sanitizes TimeframeV2 to have a from date that comes before the to date and ensures the times are applied properly.
 * @internal
 */
export function _sortTimeframeV2Values(value: Partial<TimeframeV2>) {
  if (
    value?.from?.absoluteDate &&
    value?.to?.absoluteDate &&
    isBefore(new Date(value.to.absoluteDate), new Date(value.from.absoluteDate))
  ) {
    // Swaps the `from` and the `to`, to ensure `from` is before `to`.
    // Since the times should be kept on the position, the time value must be reevaluated with the new time offsets.
    return {
      from: _getTimeValueFromSimpleValue(
        value.to.absoluteDate,
        value.from.absoluteDate,
        'from',
      ),
      to: _getTimeValueFromSimpleValue(
        value.from.absoluteDate,
        value.to.absoluteDate,
        'to',
      ),
    };
  }

  return {
    from: value?.from,
    to: value?.to,
  };
}

/**
 * Converts a given Date or ISO string to the TimeValue structure for the calendar value.
 * @internal
 */
export const _getTimeValueFromSimpleValue = (
  candidate?: string | Date | null,
  timeOffset?: _StringTimeOffset,
  position?: _CalendarState['position'],
) => {
  if (!candidate) {
    return undefined;
  }

  const stringDate =
    typeof candidate === 'string' ? candidate : candidate.toISOString();
  const parsedDate = _parseTime(stringDate);

  if (!parsedDate) {
    return undefined;
  }

  const dateWithTime = _getPreciseIsoString(
    new Date(parsedDate.absoluteDate),
    timeOffset,
    position,
  );

  if (parsedDate?.type === 'iso8601') {
    return { ...parsedDate, absoluteDate: dateWithTime, value: dateWithTime };
  }

  return { ...parsedDate, absoluteDate: dateWithTime };
};

/** Applies the proper timeoffset and returns the date as ISO String. */
function _getPreciseIsoString(
  date: Date,
  timeOffset?: _StringTimeOffset,
  position?: _CalendarState['position'],
) {
  if (!timeOffset) {
    return date.toISOString();
  }

  const offsetDate = _isSimpleTimeOffset(timeOffset)
    ? timeOffset
    : timeOffset[position ?? 'from'];

  switch (offsetDate) {
    case 'startOfDay':
      return startOfDay(date).toISOString();
    case 'endOfDay':
      return endOfDay(date).toISOString();
    default: {
      const precision = _getSecondFractions(offsetDate);
      return _applyInitialTime(date, new Date(offsetDate), precision);
    }
  }
}
